import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readdirSync } from 'node:fs';
import { JOBS } from '../src/jobs/index.js';

// #9, #12: the 500 body is shown on the scheduler's admin screen, so no job may put the
// internal error text in it (see CONTRIBUTING.md). This checks every job in JOBS, so a new
// job is covered without its own test.

// A db whose every method throws, whatever the job calls.
const brokenDb = new Proxy({}, {
  get: () => () => { throw new Error('db down at 10.0.0.5'); },
});

for (const [name, job] of Object.entries(JOBS)) {
  test(`${name}: the 500 body does not carry the internal error text`, () => {
    const res = job.run({ db: brokenDb, email: 'a@example.com' });
    assert.equal(res.status, 500);
    assert.equal(res.body.error, 'internal error');
    assert.doesNotMatch(JSON.stringify(res.body), /db down|10\.0\.0\.5/);
  });
}

// The check above only reaches jobs listed in JOBS; a job file left out of it would slip through.
test('every file in src/jobs is listed in JOBS', () => {
  const files = readdirSync(new URL('../src/jobs/', import.meta.url))
    .filter((f) => f.endsWith('.js') && f !== 'index.js')
    .map((f) => f.slice(0, -3))
    .sort();
  assert.deepEqual(Object.keys(JOBS).sort(), files);
});
EOF
